referenceSolutions.javascript:
export function solve(period, operations) {
  let now = 0,
    next = null;
  const ticks = [];
  for (const [op, n] of operations) {
    if (op === "resume") {
      if (next === null) next = now + period;
    } else if (op === "pause") next = null;
    else {
      now += n;
      while (next !== null && next <= now) {
        ticks.push(next);
        next += period;
      }
    }
  }
  return ticks;
}

