type Value = any;
export function solve(period: Value, operations: Value): Value {
  let now = 0;
  let next: number | null = null;
  const ticks: Value[] = [];
  for (const [op, n] of operations) {
    if (op === "resume") {
      if (next === null) next = now + period;
    } else if (op === "pause") next = null;
    else {
      now += n;
      while (next !== null && next <= now) {
        ticks.push(next);
        next += period;
      }
    }
  }
  return ticks;
}
